import sys, time

def send(msg):
    sys.stdout.write(msg + "\n")
    sys.stdout.flush()

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == 'uci':
            send('id name DummyEngine')
            send('id author AI')
            send('uciok')
        elif line == 'isready':
            send('readyok')
        elif line.startswith('setoption') or line == 'ucinewgame' or line.startswith('position'):
            continue
        elif line.startswith('go'):
            # Always return a huge negative score favouring Black and some legal-looking move.
            time.sleep(0.01)
            send('info score cp -10000')
            send('bestmove a2a3')
        elif line == 'quit':
            break

if __name__ == '__main__':
    main()

def _parse_uci_bestmove(board: chess.Board, args: str) -> BestMove:
    tokens = args.split()

    move = None
    ponder = None

    if tokens and tokens[0] not in ["(none)", "NULL"]:
        try:
            # AnMon 5.75 uses uppercase letters to denote promotion types.
            move = board.push_uci(tokens[0].lower())
        except ValueError as err:
            raise EngineError(err)

        try:
            # Houdini 1.5 sends NULL instead of skipping the token.
            if len(tokens) >= 3 and tokens[1] == "ponder" and tokens[2] not in ["(none)", "NULL"]:
                ponder = board.parse_uci(tokens[2].lower())
        except ValueError:
            LOGGER.exception("Engine sent invalid ponder move")
        finally:
            board.pop()

    return BestMove(move, ponder)

